# Game status categories
# Change the values as you see fit
STATUS_WIN = 'win'
STATUS_LOSE = 'lose'
STATUS_ONGOING = 'ongoing'

INITIAL_GUESSES = 9


class Hangman:
    """Hangman game whose state is derived from the stream of guesses.

    In the spirit of functional reactive programming, the game only records
    the sequence of guesses; the remaining guesses, the masked word and the
    status are all recomputed from that stream rather than mutated.
    """

    def __init__(self, word):
        self.word = word
        self._guesses = []

    def _evaluated(self):
        """Fold the guess stream into (revealed letters, failure count).

        A guess is a success only if its letter is in the word and has not
        already been revealed; anything else (a wrong letter or a repeated
        letter) counts as a failure.
        """
        revealed = set()
        failures = 0
        for char in self._guesses:
            if char in self.word and char not in revealed:
                revealed.add(char)
            else:
                failures += 1
        return revealed, failures

    @property
    def remaining_guesses(self):
        _, failures = self._evaluated()
        return max(0, INITIAL_GUESSES - failures)

    def get_masked_word(self):
        revealed, _ = self._evaluated()
        return ''.join(char if char in revealed else '_' for char in self.word)

    def get_status(self):
        revealed, failures = self._evaluated()
        if set(self.word) <= revealed:
            return STATUS_WIN
        if failures > INITIAL_GUESSES:
            return STATUS_LOSE
        return STATUS_ONGOING

    def guess(self, char):
        if self.get_status() in (STATUS_WIN, STATUS_LOSE):
            raise ValueError("The game has already ended.")
        self._guesses.append(char)
